-- Import des courriers arrivées 2017
-- Source : 2017.xlsx (feuille 2017).
--
--   N° ARR                    -> txt_numdordre (00001/jj-mm-aaaa)
--   DATE CREATION             -> dt_datearrivee
--   N° CORRESP. ET DATE       -> txt_reference, txt_numcourier, dt_datecourier
--   PRENOMS + NOMS            -> txt_prenomNom et txt_expediteur
--   DESIGNATIONS              -> txt_objet, puis txt_designation et txt_categorie
--   N° TF                     -> txt_numTitreFoncier
--   ANCIEN N° TF              -> txt_numTitreMere
--   N° LOT                    -> txt_numLot
--   SITUATION/LOTISSEMENT     -> txt_lotissement
--   AGENTS TRAITEURS          -> txt_agenttraiteur
--   OBSERVATIONS              -> txt_observation
--   N° BE DEP et DATE DEPART  -> ajoutés à txt_observation
--
-- txt_categorie déduite de la désignation (liste du formulaire).
-- txt_typecourrier = BE si la désignation commence par « BE », sinon Individuel
-- txt_nombrepiece = 1
-- Une correspondance qui n'est qu'un numéro de série Excel est ignorée.
-- Dates d'arrivée en 2018, un an après la date de correspondance : ramenées à 2017.
-- Dates ainsi corrigées : 16
-- Autres dates reconstituées : 2
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Références en doublon : suffixe [n° d'ordre]
-- Lignes importées : 2274
-- Lignes non importées :
--   ligne Excel 2273 : N° d'arrivée illisible (vide / XEEWEL SA  / Cession définitive)
--   ligne Excel 2274 : N° d'arrivée illisible (vide / Aliou CISSE / Demande de régularisation)
--   ligne Excel 2278 : N° d'arrivée illisible (N° ARR / Cheikh AW / Plan de situation)
--
-- Répartition des catégories :
--    1870  Demande SERVICES
--     293  Information
--      65  Convocation - Invitation
--      45  Réquisition - Instruction
--       1  Réclamation - Signalement
-- Désignations :
--     788  Morcellements
--     288  Demande de situation foncière
--     282  Demande de Régularisation par voie de Bail
--     252  Demande de Cession définitive
--     240  Transmission lettre
--      79  Demande de délimitation
--      49  Demande d'états des lieux
--      45  Instruction à suivre
--      41  Réunion
--      30  Duplication de CIC
--      28  Autres
--      26  Demande de terrain/Echange
--      21  Demande d'extraits de plan
--      14  Formation
--      10  Document administratif
--      10  Demande d'évaluation
--      10  Tribunal
--      10  Autorisation de lotir
--       8  Atelier
--       7  Note de service
--       6  Litiges
--       5  Réquisition d'immatriculation
--       4  Décision - Arrêté
--       4  Réceptions de lotissements
--       3  Demande d'attestation du Cadastre
--       3  Demande de Titre foncier
--       3  Autorisation de construction
--       2  PV - Compte - rendu
--       2  Visite de site
--       1  Demande de CIC
--       1  Lettre
--       1  Rapport
--       1  Plainte

SET NAMES utf8mb4;

START TRANSACTION;







COMMIT;
